function countdownParse(s){
  s=String(s||'').trim(); if(!s) return null;
  var iso=s.replace(' ','T');
  var dt=new Date(iso);
  if(!isNaN(dt.getTime())) return dt;
  var d2=new Date(s);
  return isNaN(d2.getTime())? null : d2;
}
function countdownRemain(target, now){
  target=target instanceof Date? target : countdownParse(target);
  now=now||new Date();
  var ms=target.getTime()-now.getTime();
  if(ms<=0) return { done:true, ms:0, d:0, h:0, m:0, s:0 };
  var d=Math.floor(ms/86400000); ms-=d*86400000;
  var h=Math.floor(ms/3600000); ms-=h*3600000;
  var m=Math.floor(ms/60000); ms-=m*60000;
  var sec=Math.floor(ms/1000);
  return { done:false, ms:target.getTime()-now.getTime(), d:d, h:h, m:m, s:sec };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { countdownParse:countdownParse, countdownRemain:countdownRemain };
}
if (typeof window !== 'undefined') {
  window.CountdownForgePure = { countdownParse:countdownParse, countdownRemain:countdownRemain };
}
